def fusionner(anciens, nouveaux):
    resultat={}
    for r in anciens+nouveaux:
        if r['key'] not in resultat or r['at']>=resultat[r['key']]['at']:resultat[r['key']]=dict(r)
    return sorted(resultat.values(),key=lambda r:r['key'])
